// ============================================================================
// I2C_apb: APB4 register wrapper around I2C_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/I2C.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/I2C.md
// ============================================================================
module I2C_apb #(
  parameter int I2C_ADDR = 7'h50
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  inout tri sda,
  input logic scl
);
  localparam logic [31:0] ID_VALUE = 32'h49430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [7:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd8) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_tx_byte;
  logic [7:0]    c_rx_byte;
  logic          c_rx_valid;
  logic          c_busy;
  logic          c_irq;
  I2C_top #(.I2C_ADDR(I2C_ADDR)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sda(sda),
    .scl(scl),
    .tx_byte(c_tx_byte),
    .rx_byte(c_rx_byte),
    .rx_valid(c_rx_valid),
    .busy(c_busy),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] r_TX;   // 12'h014 TX
  logic [7:0] h_RX;   // 12'h018 RX holding register
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_TX <= 8'h0;
      h_RX <= '0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_TX <= (r_TX & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (c_rx_valid && (!avail_RX || (rd && hit[6]))) begin
        h_RX[7:0] <= c_rx_byte[7:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[6]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_byte = r_TX[7:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = c_rx_valid & (~avail_RX | (rd & hit[6]));
    irq_set[2] = c_rx_valid & avail_RX & ~(rd & hit[6]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_RX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_TX);
      10'd6: apb_rdata = 32'(h_RX);
      10'd7: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
